<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/industry-classes.php';
$user=require_role('admin','staf_bkk');industry_require_ready();$id=positive_id($_GET['id']??'');if(!$id){panel_not_found();}
try{$class=industry_find($id);}catch(InvalidArgumentException){panel_not_found();}
$speakers=panel_query('SELECT s.nama,s.instansi FROM speakers s JOIN industry_class_speakers r ON r.speaker_id=s.id WHERE r.class_id=:id ORDER BY s.nama,s.id',['id'=>$id])->fetchAll();$names=implode(', ',array_column($speakers,'nama'));
$meetings=panel_query('SELECT a.*,s.nama AS pemateri_nama FROM industry_class_meetings a LEFT JOIN speakers s ON s.id=a.pemateri_id WHERE a.class_id=:id ORDER BY a.urutan,a.id',['id'=>$id])->fetchAll();$completed=count(array_filter($meetings,static fn($row)=>$row['status']==='terlaksana'));
$participantTotal=(int)panel_query('SELECT COUNT(*) FROM industry_class_participants WHERE class_id=:id',['id'=>$id])->fetchColumn();$pages=max(1,(int)ceil($participantTotal/50));$page=min($pages,positive_id($_GET['page']??'1')??1);
$participants=panel_query('SELECT s.nis,s.nama,s.kelas,s.jurusan FROM siswa s JOIN industry_class_participants r ON r.siswa_id=s.id WHERE r.class_id=:id ORDER BY s.nama,s.id LIMIT :limit OFFSET :offset',['id'=>$id,'limit'=>50,'offset'=>($page-1)*50])->fetchAll();
panel_start($user,'Kelas Industri — '.$class['nama'],'kelas-industri');
?>
<div class="page-actions"><h1><?= e($class['nama']) ?></h1><a href="<?= e(base_url('panel/kelas-industri/')) ?>">Daftar kelas</a><a href="<?= e(base_url('panel/kelas-industri/form.php?id='.$id)) ?>">Edit kelas / peserta</a><a href="<?= e(base_url('panel/kelas-industri/unduh.php?id='.$id)) ?>">Unduh rekap Excel</a></div>
<section class="card"><h2>Rencana dan pelaksanaan</h2><p><strong><?= $completed ?> / <?= (int)$class['rencana_pertemuan'] ?> pertemuan terlaksana</strong></p><progress value="<?= $completed ?>" max="<?= (int)$class['rencana_pertemuan'] ?>" aria-label="<?= $completed ?> dari <?= (int)$class['rencana_pertemuan'] ?> pertemuan terlaksana"></progress><dl class="response-details"><dt>Mitra industri</dt><dd><?= e($class['mitra_nama']) ?></dd><dt>Pemateri kelas</dt><dd><?= e($names) ?></dd><dt>Kelas sasaran</dt><dd><?= e($class['kelas_sasaran']?:'Peserta terdaftar di bawah') ?></dd><dt>Peserta terdaftar</dt><dd><?= $participantTotal ?> siswa</dd><dt>Status kelas</dt><dd><?= e(ucfirst($class['status'])) ?></dd><dt>Catatan</dt><dd><?= nl2br(e($class['catatan']?:'—')) ?></dd></dl></section>
<h2>Jadwal setiap pertemuan</h2><p>Hanya status Terlaksana dihitung selesai. Pertemuan ditunda/dibatalkan tidak menambah capaian. Pemateri per pertemuan dapat berbeda dari pemateri kelas.</p>
<div class="table-scroll"><table><thead><tr><th>Pertemuan</th><th>Tanggal / jam WIB</th><th>Lokasi</th><th>Pemateri</th><th>Materi / catatan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($meetings as $meeting): ?><tr><td><?= (int)$meeting['urutan'] ?></td><td><?= e($meeting['tanggal']?:'Belum dijadwalkan') ?><br><?= e($meeting['jam']?substr($meeting['jam'],0,5):'') ?></td><td><?= e($meeting['lokasi']?:'—') ?></td><td><?= e($meeting['pemateri_nama']?:$names) ?></td><td><?= nl2br(e($meeting['materi'])) ?><p><?= nl2br(e($meeting['catatan'])) ?></p></td><td><?= e(industry_meeting_statuses()[$meeting['status']]) ?></td><td><a href="<?= e(base_url('panel/kelas-industri/pertemuan.php?class_id='.$id.'&id='.$meeting['id'])) ?>">Edit jadwal / status</a></td></tr><?php endforeach; ?></tbody></table></div>
<h2>Peserta terdaftar</h2><div class="table-scroll"><table><thead><tr><th>NIS</th><th>Nama</th><th>Kelas</th><th>Jurusan</th></tr></thead><tbody><?php foreach($participants as $participant): ?><tr><?php foreach(['nis','nama','kelas','jurusan'] as $key): ?><td><?= e($participant[$key]) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$participants): ?><tr><td colspan="4">Peserta belum dipilih satu per satu. Sasaran kelas: <?= e($class['kelas_sasaran']) ?></td></tr><?php endif; ?></tbody></table></div>
<nav class="pagination" aria-label="Halaman peserta kelas industri"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;} ?><a href="<?= e(base_url('panel/kelas-industri/detail.php?id='.$id.'&page='.$target)) ?>"><?= $label ?></a><?php endforeach; ?></nav>
<?php panel_end($user); ?>
